<script lang="ts">
 import {onMount} from 'svelte';
 import {invalidateAll} from '$app/navigation';

 import SourceReader from '$lib/components/harness/SourceReader.svelte';
 import Icon from '$lib/components/harness/Icon.svelte';
 import {createCollection} from '$lib/harness/social.svelte';
 import {dateLabel,pinnedUrl} from '$lib/harness/types';
 import type {PageData} from './$types';
 let {data}:{data:PageData}=$props();const collection=createCollection();let refreshing=$state(false),refreshMessage=$state('');
 let h=$derived(data.harness);onMount(()=>{collection.load();});
 async function refresh(){refreshing=true;refreshMessage='';try{const {auth}=await import('$lib/firebase');await auth.authStateReady();if(!auth.currentUser)throw new Error('Sign in again to refresh your file.');const res=await fetch(`/api/harnesses/${h.id}/refresh`,{method:'POST',headers:{Authorization:`Bearer ${await auth.currentUser.getIdToken()}`}});const result=await res.json();if(!res.ok)throw new Error(result.error);refreshMessage=result.changed?'A new snapshot was saved.':'Your snapshot is already up to date.';await invalidateAll();}catch(e){refreshMessage=e instanceof Error?e.message:'Refresh failed.';}finally{refreshing=false;}}
</script>
<svelte:head><title>{h.title} — Loooom</title><meta name="description" content={h.description}/></svelte:head>
<div class="page-intro"><a href="/#discover" class="back-link">Browse harnesses</a><div class="reader-author"><a href={`/people/${h.snapshot.owner}`}>@{h.snapshot.owner}</a><span>{h.curated?'Curated from GitHub':`Shared by @${h.sharedBy}`}</span></div><h1>{h.title}</h1><p>{h.description}</p></div>
 <div class="reader-actions"><a class="button primary" href={pinnedUrl(h.snapshot)} target="_blank" rel="noreferrer">View on GitHub <Icon name="external" size={15}/></a><button class="button secondary" disabled={!!collection.busy} onclick={()=>collection.toggle('save',h.id)}><Icon name="bookmark" size={16}/>{collection.saved.includes(h.id)?'Saved to collection':'Save to collection'}</button><button class="button secondary" disabled={!!collection.busy} onclick={()=>collection.toggle('follow',h.snapshot.owner.toLowerCase())}>{collection.following.includes(h.snapshot.owner.toLowerCase())?'Following':'Follow'} @{h.snapshot.owner}</button>{#if data.user?.id===h.userId}<button class="button secondary" onclick={refresh} disabled={refreshing}><Icon name="refresh" size={16}/>{refreshing?'Refreshing…':'Refresh from GitHub'}</button>{/if}</div>
 {#if collection.message}<div class="notice" role="status">{collection.message} {#if collection.message.startsWith('Sign in')}<a href={`/login?next=/h/${h.id}`}>Sign in</a>{/if}</div>{/if}{#if refreshMessage}<div class="notice" role="status">{refreshMessage}</div>{/if}
 <dl class="source-facts"><div><dt>Source file</dt><dd>{h.snapshot.owner}/{h.snapshot.repo}<br/>{h.snapshot.path}</dd></div><div><dt>Last file update</dt><dd>{dateLabel(h.snapshot.updatedAt)}</dd></div><div><dt>Commit</dt><dd><a href={`https://github.com/${h.snapshot.owner}/${h.snapshot.repo}/commit/${h.snapshot.commitSha}`} target="_blank" rel="noreferrer">{h.snapshot.commitSha.slice(0,12)} <Icon name="external" size={12}/></a></dd></div><div><dt>Length</dt><dd>{h.snapshot.lineCount} lines</dd></div></dl>
 <SourceReader content={h.snapshot.content} filename={h.snapshot.path}/>
 <div class="source-end"><span>Imported {dateLabel(h.snapshot.importedAt)} · Read-only snapshot</span><span class="hash">SHA-256 {h.snapshot.contentHash}</span></div><div class="reader-eval"><Icon name="flask" size={26}/><div><h2>Test the fit.</h2><p>Compare answers with and without this file.</p></div><a href="/evals" class="button secondary">Personal evals <Icon name="arrow" size={16}/></a></div>

<style>
 .reader-author{display:flex;gap:12px;font-size:12px;margin-top:28px;align-items:center}.reader-author>a{color:var(--lime)}.reader-author>span{color:var(--quiet);font-size:11px}.page-intro h1{font-size:clamp(36px,4vw,58px);max-width:18ch}.reader-actions{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:30px}.reader-actions button,.reader-actions a{font-size:12px}.source-facts{display:grid;grid-template-columns:1.6fr 1fr 1fr .6fr;gap:20px;border-top:1px solid var(--line);padding:24px 0;margin:0}.source-facts dt{font-size:11px;color:var(--quiet);margin-bottom:8px}.source-facts dd{margin:0;font-family:'Space Mono',monospace;font-size:11px;overflow-wrap:anywhere}.source-facts dd a{display:inline-flex;gap:6px;align-items:center}.source-end{padding:18px 0;color:var(--quiet);font-size:10px;display:flex;flex-direction:column;gap:6px}.hash{font-family:'Space Mono',monospace;font-size:9px;overflow-wrap:anywhere}.reader-eval{padding:30px 0;border-top:1px solid var(--line);display:flex;align-items:center;gap:20px;margin-top:30px}.reader-eval>:global(svg){color:var(--lavender)}.reader-eval h2{font-size:22px;margin:0 0 7px}.reader-eval p{font-size:13px;color:var(--quiet)}.reader-eval a{margin-left:auto;white-space:nowrap}@media(max-width:900px){.source-facts{grid-template-columns:1fr 1fr}.reader-eval{flex-wrap:wrap}.reader-eval a{margin:0}}@media(max-width:500px){.reader-actions{gap:9px}.reader-actions button,.reader-actions a{font-size:11px;padding:10px 13px}.source-facts dd{font-size:10px}.reader-eval h2{font-size:20px}}
</style>
